/* @lc app=leetcode id=2791 lang=kotlin */
class Solution { fun countPalindromePaths(parent: List<Int>, s: String): Long = parent.indices.groupBy { parent[it] }.let { adj -> LongArray(parent.size).also { masks -> DeepRecursiveFunction<Pair<Int, Int>, Unit> { (u, m) -> masks[u] = m.toLong().also { adj[u]?.forEach { v -> callRecursive(v to (m xor (1 shl (s[v] - 'a')))) } } }.callRecursive(0 to 0) }.let { masks -> masks.toList().groupingBy { it }.eachCount().let { freq -> freq.entries.sumOf { (m, f) -> f.toLong() * (f - 1) / 2 + (0..25).sumOf { b -> (m xor (1L shl b)).let { m2 -> if (m2 > m) f.toLong() * (freq[m2] ?: 0) else 0L } } } } } } }